{
  "vulnerable_symbols": [
    "urlize",
    "jinja2.filters.urlize"
  ],
  "trigger": "当外部可控字符串被传入 Jinja2 模板的 urlize 过滤器渲染时，构造特定长输入可触发正则回溯导致拒绝服务。",
  "preconditions": [
    "Jinja2 版本低于 2.11.3"
  ],
  "exploit_evidence": [
    {
      "src": 1,
      "kind": "poc",
      "quote": "11 CVE-2020-28493 jinja2 Yes 09/25/2020 Yeting Li"
    },
    {
      "src": 7,
      "kind": "poc",
      "quote": "Snyk has a proof-of-concept or detailed explanation of how to exploit this vulnerability."
    }
  ],
  "fixed_version": "2.11.3",
  "summary_zh": "Jinja2 2.10 的 urlize 过滤器存在 ReDoS，外部输入可致拒绝服务，请升级至 2.11.3 或避免对不可信内容使用 urlize。"
}
